#include <iostream>
#include <cstdio>
#include <cstring>
#include <cctype>

#include <vector>
#include <queue>

using namespace std;

#define SZ(a) int((a).size())

#define REP(i,n) for(int i=0,_n=(n);i<_n;++i)
#define FOR(i,a,b) for(int i=(a),_b=(b);i<=_b;++i)

struct Pos {
   int row, col;
   Pos(int _row=0, int _col=0) : row(_row), col(_col) {}
};

int dr[] = {-1, 0, 0, 1};
int dc[] = {0, -1, 1, 0};

int N, T;
char B[12][12];
char B1[12][12];
char B2[12][12];

// time to infect all cells
int D1[12][12];
void bfs1(const Pos& src) {
   memset(D1, -1, sizeof(D1));
   D1[src.row][src.col] = 0;
   queue<Pos> q;
   q.push(src);
   while (!q.empty()) {
      Pos cur = q.front();
      q.pop();
      REP(k, 4) {
         Pos nxt(cur.row + dr[k], cur.col + dc[k]);
         if (B[nxt.row][nxt.col] != '.') continue;
         if (D1[nxt.row][nxt.col] < 0) {
            D1[nxt.row][nxt.col] = D1[cur.row][cur.col] + 1;
            q.push(nxt);
         }
      }
   }
}

int D2[12][12];
void bfs2(const Pos& src) {
   memset(D2, -1, sizeof(D2));
   D2[src.row][src.col] = 0;
   queue<Pos> q;
   q.push(src);
   while (!q.empty()) {
      Pos cur = q.front();
      q.pop();
      if (D1[cur.row][cur.col] >= 0 &&
          D2[cur.row][cur.col] >= D1[cur.row][cur.col])
         continue;
      REP(k, 4) {
         Pos nxt(cur.row + dr[k], cur.col + dc[k]);
         if (B[nxt.row][nxt.col] != '.') continue;
         if (D2[nxt.row][nxt.col] < 0) {
            if (D1[nxt.row][nxt.col] >= 0 &&
                D1[nxt.row][nxt.col] < D2[cur.row][cur.col] + 1)
               continue;
            D2[nxt.row][nxt.col] = D2[cur.row][cur.col] + 1;
            q.push(nxt);
         }
      }
   }
}


typedef vector<int> VI;
typedef vector<VI> VVI;

#define HIGHESTSETBIT(mask) ( sizeof(int)*8-1-__builtin_clz((mask)) )

#define INF 98765432

class MaxFlow {
   size_t N;
   VI bfs_par, bfs_D;
   int augmenting_path_bfs(int src, int dst, VI& path, int mincap=0);
// int augmenting_path_pfs(int src, int dst, VI& path, int mincap=0);

public:
   VVI cap;
// VVI adj;

   // OUTPUT:
   VVI flow;

   MaxFlow(int _N) : cap(_N, VI(_N)) {}
   void add_edge(int u, int v, int _cap=1);

   // Dinitz's Algoritm -- O(V^2 * E)
   int dinic(int s, int t);
};

inline void MaxFlow::add_edge(int u, int v, int _cap) {
   cap[u][v] += _cap;
}

int MaxFlow::augmenting_path_bfs(int src, int dst, VI& path, int mincap) {
   bfs_par.assign(N, -1);
   bfs_D.assign(N, -1);

   bfs_D[src] = 0;
   queue<int> q;
   q.push(src);
   while (!q.empty()) {
      int cur = q.front();
      q.pop();
      if (cur == dst) {
         int cfp = INF;
         path.resize(bfs_D[dst]+1);
         path[bfs_D[dst]] = dst;
         for (int curv = dst, k = bfs_D[dst]-1; bfs_par[curv] >= 0; --k) {
            int prev = bfs_par[curv];
            cfp = min(cfp, cap[prev][curv] - flow[prev][curv]);
            curv = path[k] = prev;
         }
         return cfp;
      }
      for (int v = 0; v < N; ++v) {
         if (bfs_D[v] < 0 && cap[cur][v] - flow[cur][v] > mincap) {
            bfs_D[v] = bfs_D[cur]+1;
            bfs_par[v] = cur;
            q.push(v);
         }
      }
   }
   path.clear();
   return 0;
}

int MaxFlow::dinic(int s, int t) {
   N = cap.size();
   flow = VVI(N, VI(N, 0));

   VI path;
   int res = 0;

   while (true) {
      // find an augmenting path
      int cfp = augmenting_path_bfs(s, t, path);
      if (path.empty())
         break;

      // try finding more paths
      for (int w = 0; w < N; ++w) {
         if (bfs_D[w] >= 0 && cap[w][t] - flow[w][t] > 0) {
            cfp = cap[w][t] - flow[w][t];
            for (int curv = w, prev = bfs_par[w]; prev >= 0;
                 curv = prev, prev = bfs_par[prev])
               cfp = min(cfp, cap[prev][curv] - flow[prev][curv]);
            flow[w][t] += cfp;
            flow[t][w] = -flow[w][t];  // -= cfp;
            for (int curv = w, prev = bfs_par[w]; prev >= 0;
                 curv = prev, prev = bfs_par[prev]) {
               flow[prev][curv] += cfp;
               flow[curv][prev] = -flow[prev][curv]; // -= cfp;
            }
            res += cfp;
         }
      }
   }
   return res;
}


int main(int argc, char* argv[]) {
   ios_base::sync_with_stdio(false); 

   cin >> N >> T;
   memset(B1, '#', sizeof(B1));
   FOR(r, 1, N) {
      cin >> B1[r]+1;
      B1[r][N+1] = '#';
   }

   memset(B2, '#', sizeof(B2));
   FOR(r, 1, N) {
      cin >> B2[r]+1;
      B2[r][N+1] = '#';
   }

   memset(B, '#', sizeof(B));
   vector<Pos> scientists;
   vector<Pos> capsules;
   Pos z;
   FOR(r, 1, N) FOR(c, 1, N) {
      if (isdigit(B1[r][c])) {
         if (B1[r][c] > '0')
            scientists.push_back(Pos(r, c));
         B[r][c] = '.';
      }
      else
      if (B1[r][c] == 'Z') {
         z = Pos(r, c);
         B[r][c] = '.';
      }
      if (isdigit(B2[r][c]) && B2[r][c] > '0')
         capsules.push_back(Pos(r, c));
   }

   bfs1(z);
/*
   FOR(r, 1, N) {
      FOR(c, 1, N) {
         fprintf(stderr, "%3d ", D1[r][c]);
      }
      fprintf(stderr, "\n");
   }
*/

   const int SRC  = 0;
   const int SINK = SZ(scientists) + SZ(capsules) + 1;

   MaxFlow mf(SINK+1);
   REP(i, SZ(scientists)) {
      const Pos& s = scientists[i];
      mf.add_edge(SRC, i+1, B1[ s.row ][ s.col ] - '0');
   }

   REP(j, SZ(capsules)) {
      const Pos& c = capsules[j];
      mf.add_edge(SZ(scientists)+j+1, SINK, B2[ c.row ][ c.col ]-'0' );
   }

   REP(i, SZ(scientists)) {
      const Pos& s = scientists[i];
      bfs2(s);
/*
      fprintf(stderr, "(%d,%d)\n", s.row, s.col);
      FOR(r, 1, N) {
         FOR(c, 1, N) {
            fprintf(stderr, "%3d ", D2[r][c]);
         }
         fprintf(stderr, "\n");
      }      
      fprintf(stderr, "\n");
*/
      REP(j, SZ(capsules)) {
         const Pos& c = capsules[j];
         if (D2[c.row][c.col] >= 0 && D2[c.row][c.col] <= T)
            mf.add_edge( i+1, SZ(scientists)+j+1, INF );
      }
   }

   int res = mf.dinic(SRC, SINK);
   cout << res << endl;

   return 0;
}

